class TMP1075_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x0000,  # TEMP
            0x01: 0x00FF,  # CFGR
            0x02: 0x4B00,  # LLIM
            0x03: 0x5000,  # HLIM
            0x0F: 0x7500,  # DIEID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04X}")

        value = self.regs[addr]

        if nbytes == 1:
            return (value >> 8) & 0xFF

        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04X}")

        if addr == 0x00 or addr == 0x0F:
            # Read-only registers
            return

        if nbytes == 1:
            # Single byte write updates only bits 15:8
            mask = 0xFF << 8
            self.regs[addr] = (self.regs[addr] & ~mask) | (data << 8)
        else:
            # Full register write
            self.regs[addr] = data

        # Special handling for CFGR register
        if addr == 0x01:
            # Ensure OS bit always reads as 0
            self.regs[addr] &= ~(1 << 15)

